-- REVIEW ONLY. Coherent ORS foundation; never imported by application startup.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
DO $$ BEGIN
 IF current_database()<>'vtv_saas_dev' OR host(inet_server_addr())<>'127.0.0.1' OR inet_server_port()<>55440
 OR session_user<>'vtv_saas_operator' OR current_user<>session_user
 OR replace(current_setting('data_directory'),E'\\','/')<>'D:/vetthevat.saas-dev/cluster'
 OR current_setting('server_version_num')::int NOT BETWEEN 170000 AND 179999
 OR NOT EXISTS(SELECT 1 FROM business.migrations WHERE version=3)
 OR to_regclass('operations.materials') IS NOT NULL THEN RAISE EXCEPTION 'Unapproved target or existing operations schema'; END IF;
END $$;
CREATE SCHEMA operations AUTHORIZATION vtv_saas_owner;
SET LOCAL ROLE vtv_saas_owner;
CREATE TABLE operations.materials(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES web_auth.companies(id),sku text NOT NULL CHECK(sku~'^[A-Z0-9][A-Z0-9._/-]{0,79}$'),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),unit text NOT NULL CHECK(unit~'^[A-Z0-9][A-Z0-9._/-]{0,15}$'),reorder_point numeric(18,4) NOT NULL CHECK(reorder_point>0),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','archived')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,sku),UNIQUE(company_id,id));
CREATE TABLE operations.warehouses(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES web_auth.companies(id),code text NOT NULL CHECK(code~'^[A-Z0-9][A-Z0-9._/-]{0,39}$'),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','archived')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,code),UNIQUE(company_id,id));
CREATE TABLE operations.stock_locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,warehouse_id uuid NOT NULL,code text NOT NULL CHECK(code~'^[A-Z0-9][A-Z0-9._/-]{0,39}$'),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','archived')),UNIQUE(company_id,warehouse_id,code),UNIQUE(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES operations.warehouses(company_id,id));
CREATE TABLE operations.purchase_requests(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES web_auth.companies(id),supplier_id uuid NOT NULL,requested_on date NOT NULL,notes text, state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','approved','ordered','cancelled')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES web_auth.users(id),approved_by uuid REFERENCES web_auth.users(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,supplier_id) REFERENCES business.counterparties(company_id,id));
CREATE TABLE operations.purchase_request_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,request_id uuid NOT NULL,position integer NOT NULL CHECK(position BETWEEN 1 AND 500),material_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),UNIQUE(company_id,request_id,position),UNIQUE(company_id,request_id,material_id),FOREIGN KEY(company_id,request_id) REFERENCES operations.purchase_requests(company_id,id),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id));
CREATE TABLE operations.purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES web_auth.companies(id),request_id uuid NOT NULL,supplier_id uuid NOT NULL,ordered_on date NOT NULL,state text NOT NULL DEFAULT 'ordered' CHECK(state IN('ordered','part_received','received','closed','cancelled')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,request_id),UNIQUE(company_id,id),FOREIGN KEY(company_id,request_id) REFERENCES operations.purchase_requests(company_id,id),FOREIGN KEY(company_id,supplier_id) REFERENCES business.counterparties(company_id,id));
CREATE TABLE operations.purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,purchase_order_id uuid NOT NULL,position integer NOT NULL CHECK(position BETWEEN 1 AND 500),material_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),received_quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(received_quantity BETWEEN 0 AND quantity),UNIQUE(company_id,purchase_order_id,position),UNIQUE(company_id,purchase_order_id,material_id),FOREIGN KEY(company_id,purchase_order_id) REFERENCES operations.purchase_orders(company_id,id),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id));
CREATE TABLE operations.goods_receipts(id uuid PRIMARY KEY,company_id uuid NOT NULL,purchase_order_id uuid NOT NULL,received_on date NOT NULL,reference text NOT NULL CHECK(length(reference) BETWEEN 1 AND 100),state text NOT NULL DEFAULT 'posted' CHECK(state='posted'),received_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,purchase_order_id,reference),UNIQUE(company_id,id),FOREIGN KEY(company_id,purchase_order_id) REFERENCES operations.purchase_orders(company_id,id));
CREATE TABLE operations.goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,receipt_id uuid NOT NULL,material_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),UNIQUE(company_id,receipt_id,material_id),FOREIGN KEY(company_id,receipt_id) REFERENCES operations.goods_receipts(company_id,id),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id));
CREATE TABLE operations.inventory_movements(id uuid PRIMARY KEY,company_id uuid NOT NULL,material_id uuid NOT NULL,location_id uuid,quantity numeric(18,4) NOT NULL CHECK(quantity<>0),kind text NOT NULL CHECK(kind IN('receipt','adjustment','transfer_out','transfer_in','reservation','release','dispatch','return')),reference text NOT NULL CHECK(length(reference) BETWEEN 1 AND 100),source_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id),FOREIGN KEY(company_id,location_id) REFERENCES operations.stock_locations(company_id,id));
CREATE INDEX inventory_movement_company_material ON operations.inventory_movements(company_id,material_id,created_at,id);
CREATE TABLE operations.stock_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,sales_order_id uuid NOT NULL,material_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','released','consumed')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,sales_order_id,material_id));
CREATE TABLE operations.stock_transfers(id uuid PRIMARY KEY,company_id uuid NOT NULL,material_id uuid NOT NULL,from_location_id uuid NOT NULL,to_location_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),reference text NOT NULL CHECK(length(reference) BETWEEN 1 AND 100),state text NOT NULL DEFAULT 'posted' CHECK(state='posted'),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_location_id<>to_location_id),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id),FOREIGN KEY(company_id,from_location_id) REFERENCES operations.stock_locations(company_id,id),FOREIGN KEY(company_id,to_location_id) REFERENCES operations.stock_locations(company_id,id));
CREATE TABLE operations.sales_orders(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES web_auth.companies(id),customer_id uuid NOT NULL,ordered_on date NOT NULL,notes text,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','approved','picking','packed','dispatched','closed','returned')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,customer_id) REFERENCES business.counterparties(company_id,id));
CREATE TABLE operations.sales_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,sales_order_id uuid NOT NULL,position integer NOT NULL CHECK(position BETWEEN 1 AND 500),material_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>0),fulfilled_quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(fulfilled_quantity BETWEEN 0 AND quantity),UNIQUE(company_id,sales_order_id,position),UNIQUE(company_id,sales_order_id,material_id),FOREIGN KEY(company_id,sales_order_id) REFERENCES operations.sales_orders(company_id,id),FOREIGN KEY(company_id,material_id) REFERENCES operations.materials(company_id,id));
CREATE TABLE operations.fulfilments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,sales_order_id uuid NOT NULL,status text NOT NULL CHECK(status IN('picked','packed','dispatched','returned')),tracking_reference text CHECK(length(tracking_reference)<=100),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,sales_order_id) REFERENCES operations.sales_orders(company_id,id));
CREATE TABLE operations.invoice_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,invoice_id uuid NOT NULL,purchase_order_id uuid,goods_receipt_id uuid,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','matched','exception')),created_by uuid NOT NULL REFERENCES web_auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,invoice_id),FOREIGN KEY(company_id,invoice_id) REFERENCES business.invoices(company_id,id),FOREIGN KEY(company_id,purchase_order_id) REFERENCES operations.purchase_orders(company_id,id),FOREIGN KEY(company_id,goods_receipt_id) REFERENCES operations.goods_receipts(company_id,id));
CREATE FUNCTION operations.allowed(company uuid,capability text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,saas AS $$ SELECT saas.authorized_company(company,capability) $$;
CREATE FUNCTION operations.receive_purchase_line(company uuid,receipt uuid,purchase uuid,material uuid,quantity numeric,actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations AS $$ DECLARE line operations.purchase_order_lines%ROWTYPE; BEGIN IF NOT saas.authorized_company(company,'inventory:receive') OR quantity<=0 THEN RAISE EXCEPTION 'Unauthorized receipt'; END IF; SELECT * INTO line FROM operations.purchase_order_lines WHERE company_id=company AND purchase_order_id=purchase AND material_id=material FOR UPDATE; IF NOT FOUND OR line.received_quantity+quantity>line.quantity THEN RAISE EXCEPTION 'Receipt exceeds ordered quantity'; END IF; INSERT INTO operations.goods_receipt_lines(company_id,receipt_id,material_id,quantity) VALUES(company,receipt,material,quantity); UPDATE operations.purchase_order_lines SET received_quantity=received_quantity+quantity WHERE id=line.id; INSERT INTO operations.inventory_movements(id,company_id,material_id,quantity,kind,reference,source_id,created_by) VALUES(gen_random_uuid(),company,material,quantity,'receipt',receipt::text,receipt,actor); UPDATE operations.purchase_orders SET state=CASE WHEN EXISTS(SELECT 1 FROM operations.purchase_order_lines WHERE company_id=company AND purchase_order_id=purchase AND received_quantity<quantity) THEN 'part_received' ELSE 'received' END,version=version+1 WHERE company_id=company AND id=purchase; END $$;
CREATE FUNCTION operations.adjust_stock(company uuid,movement uuid,material uuid,location uuid,quantity numeric,reason text,actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations AS $$ BEGIN IF NOT saas.authorized_company(company,'inventory:adjust') OR quantity=0 THEN RAISE EXCEPTION 'Unauthorized adjustment'; END IF; INSERT INTO operations.inventory_movements(id,company_id,material_id,location_id,quantity,kind,reference,source_id,created_by) VALUES(movement,company,material,location,quantity,'adjustment',reason,movement,actor); RETURN movement; END $$;
CREATE FUNCTION operations.transfer_stock(company uuid,transfer uuid,material uuid,from_location uuid,to_location uuid,quantity numeric,reference text,actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations AS $$ BEGIN IF NOT saas.authorized_company(company,'inventory:transfer') OR quantity<=0 OR from_location=to_location THEN RAISE EXCEPTION 'Unauthorized transfer'; END IF; INSERT INTO operations.stock_transfers(id,company_id,material_id,from_location_id,to_location_id,quantity,reference,created_by) VALUES(transfer,company,material,from_location,to_location,quantity,reference,actor); INSERT INTO operations.inventory_movements(id,company_id,material_id,location_id,quantity,kind,reference,source_id,created_by) VALUES(gen_random_uuid(),company,material,from_location,-quantity,'transfer_out',reference,transfer,actor),(gen_random_uuid(),company,material,to_location,quantity,'transfer_in',reference,transfer,actor); RETURN transfer; END $$;
CREATE FUNCTION operations.transition_sales_order(company uuid,order_id uuid,next_state text,expected_version bigint,actor uuid) RETURNS TABLE(id uuid,version bigint,state text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations AS $$ BEGIN IF NOT saas.authorized_company(company,CASE WHEN next_state='approved' THEN 'sales:approve' ELSE 'fulfilment:write' END) THEN RAISE EXCEPTION 'Unauthorized sales transition'; END IF; UPDATE operations.sales_orders SET state=next_state,version=version+1 WHERE company_id=company AND id=order_id AND version=expected_version AND ((state='draft' AND next_state='approved') OR (state='approved' AND next_state='picking') OR (state='picking' AND next_state='packed') OR (state='packed' AND next_state='dispatched') OR (state='dispatched' AND next_state IN('closed','returned'))) RETURNING operations.sales_orders.id,operations.sales_orders.version,operations.sales_orders.state INTO id,version,state; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid sales transition'; END IF; INSERT INTO operations.fulfilments(company_id,sales_order_id,status,created_by) SELECT company,order_id,next_state,actor WHERE next_state IN('picking','packed','dispatched','returned'); RETURN NEXT; END $$;
DO $$ DECLARE item text;capability text; BEGIN FOREACH item IN ARRAY ARRAY['materials','warehouses','stock_locations','purchase_requests','purchase_request_lines','purchase_orders','purchase_order_lines','goods_receipts','goods_receipt_lines','inventory_movements','stock_reservations','stock_transfers','sales_orders','sales_order_lines','fulfilments','invoice_matches'] LOOP capability:=CASE WHEN item IN('materials','purchase_requests','purchase_request_lines','purchase_orders','purchase_order_lines','invoice_matches') THEN 'procurement:write' WHEN item IN('warehouses','stock_locations') THEN 'inventory:adjust' WHEN item IN('goods_receipts','goods_receipt_lines') THEN 'inventory:receive' WHEN item='stock_transfers' THEN 'inventory:transfer' WHEN item IN('sales_orders','sales_order_lines') THEN 'sales:write' WHEN item='fulfilments' THEN 'fulfilment:write' ELSE 'inventory:adjust' END; EXECUTE format('ALTER TABLE operations.%I ENABLE ROW LEVEL SECURITY',item);EXECUTE format('ALTER TABLE operations.%I FORCE ROW LEVEL SECURITY',item);EXECUTE format('CREATE POLICY runtime_read ON operations.%I FOR SELECT TO vtv_saas_runtime USING(operations.allowed(company_id,''company:read''))',item);EXECUTE format('CREATE POLICY runtime_write ON operations.%I FOR INSERT TO vtv_saas_runtime WITH CHECK(operations.allowed(company_id,%L))',item,capability);EXECUTE format('CREATE POLICY owner_all ON operations.%I FOR ALL TO vtv_saas_owner USING(true) WITH CHECK(true)',item); END LOOP; END $$;
GRANT USAGE ON SCHEMA operations TO vtv_saas_runtime;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA operations TO vtv_saas_runtime;
GRANT EXECUTE ON FUNCTION operations.receive_purchase_line(uuid,uuid,uuid,uuid,numeric,uuid),operations.adjust_stock(uuid,uuid,uuid,uuid,numeric,text,uuid),operations.transfer_stock(uuid,uuid,uuid,uuid,uuid,numeric,text,uuid),operations.transition_sales_order(uuid,uuid,text,bigint,uuid) TO vtv_saas_runtime;
REVOKE ALL ON ALL TABLES IN SCHEMA operations FROM PUBLIC,vtv_web_runtime,vtv_saas_provider_runtime;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA operations FROM PUBLIC,vtv_web_runtime,vtv_saas_provider_runtime;
COMMIT;
